import json

from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, Response

app = FastAPI()


def _reject_constant(name: str):
    # Called by json for NaN, Infinity and -Infinity, which are not valid JSON.
    raise ValueError(f"Non-standard JSON constant: {name}")


@app.get("/health")
def health():
    return {"status": "ok"}


@app.post("/echo")
async def echo(request: Request):
    # Content-Type is intentionally ignored: any body that parses as a JSON object is echoed.
    raw = await request.body()
    if not raw:
        return JSONResponse(status_code=422, content={"detail": "Request body is required"})
    try:
        payload = json.loads(raw, parse_constant=_reject_constant)
    except RecursionError:
        return JSONResponse(status_code=422, content={"detail": "JSON nested too deeply"})
    except (ValueError, UnicodeDecodeError):
        # Covers malformed JSON, whitespace-only bodies, NaN/Infinity and oversized integers.
        return JSONResponse(status_code=422, content={"detail": "Malformed JSON"})
    if not isinstance(payload, dict):
        return JSONResponse(status_code=422, content={"detail": "JSON body must be an object"})
    try:
        encoded = json.dumps(payload, allow_nan=False).encode("utf-8")
    except (ValueError, RecursionError):
        return JSONResponse(status_code=422, content={"detail": "JSON body cannot be encoded"})
    return Response(content=encoded, media_type="application/json")


