def test_missing_body_is_truly_empty_bytes():
    # Confirms that a request with no body reaches the handler as b'', not as a JSON string.
    probe = FastAPI()

    @probe.post("/probe")
    async def read_body(request: Request):
        return {"body": (await request.body()).decode("utf-8")}

    with TestClient(probe) as c:
        assert c.post("/probe").json() == {"body": ""}


