        content=b'{"a": "\xff\xfe"}',
        headers={"content-type": "application/json"},
    )
    _assert_422_with_detail(response)


def test_text_plain_with_valid_object_is_echoed(client):
    # Content-Type is ignored by design: a JSON object in a text/plain body is still echoed.
    response = client.post(
        "/echo", content=b'{"a":1}', headers={"content-type": "text/plain"}
    )
    assert response.status_code == 200
    assert response.json() == {"a": 1}


def test_valid_object_still_echoed(client):
    body = {"hello": "world", "n": [1, None, {"k": True}]}
    response = client.post("/echo", json=body)
    assert response.status_code == 200
    assert response.json() == body


def test_no_sticky_state_after_invalid_requests(client):
    # Invalid requests first, then a valid one on the same client and app.
    assert client.post("/echo", content=b"{invalid").status_code == 422
    assert client.post("/echo", json=[1]).status_code == 422
    response = client.post("/echo", json={"ok": True})
    assert response.status_code == 200
    assert response.json() == {"ok": True}

